<?php
declare(strict_types=1);
require_once __DIR__.'/money.php';require_once __DIR__.'/planning_engine.php';
interface GszSeoProvider {public function collect(array $keyword):array;}
final class GszSeoDisconnected implements GszSeoProvider {public function collect(array $keyword):array{throw new RuntimeException('BLOCKED: Keine autorisierte Rankingquelle eingerichtet. Eigene belegbare Messdaten als CSV importieren.');}}
function seoText(string $s,int $max):string {$s=trim($s);if($s===''||mb_strlen($s)>$max||!mb_check_encoding($s,'UTF-8')||preg_match('/[\x00-\x1f\x7f]/',$s))throw new InvalidArgumentException('SEO-Text fehlt/ungültig.');return $s;}
function seoCoordinate(string $s,int $bound):int {if(!preg_match('/^(-?)(\d{1,3})(?:\.(\d{1,6}))?$/D',trim($s),$m))throw new InvalidArgumentException('Koordinaten: Dezimalpunkt, maximal6Nachkommastellen.');$v=(int)$m[2]*1000000+(int)str_pad($m[3]??'',6,'0');if($v>$bound*1000000)throw new InvalidArgumentException('Koordinate außerhalb des gültigen Bereichs.');return $m[1]==='-'?-$v:$v;}
function seoParse(string $raw,int $depth):array {
 if($depth<3||$depth>100||strlen($raw)>256*1024||!mb_check_encoding($raw,'UTF-8')||str_contains($raw,"\0"))throw new InvalidArgumentException('SEO-CSV: UTF-8 bis256KB, Messtiefe3–100.');$f=fopen('php://temp','w+');try{fwrite($f,preg_replace('/^\xEF\xBB\xBF/','',$raw));rewind($f);$header=fgetcsv($f,4096,';','"','');if($header!==['punkt','breitengrad','laengengrad','position','wettbewerber','wettbewerber_position'])throw new InvalidArgumentException('Exakte SEO-Vorlagenkopfzeile erforderlich.');$points=[];$coords=[];while(($row=fgetcsv($f,4096,';','"',''))!==false){if($row===[null])continue;if(count($row)!==6)throw new InvalidArgumentException('SEO-Spaltenzahl falsch.');[$key,$lat,$lon,$rank,$competitor,$other]=array_map('trim',$row);if(!preg_match('/^[a-zA-Z0-9_.-]{1,64}$/D',$key)||isset($points[$key]))throw new InvalidArgumentException('Eindeutige Punkt-ID erforderlich.');$lat=seoCoordinate($lat,90);$lon=seoCoordinate($lon,180);$coordinate=$lat.':'.$lon;if(isset($coords[$coordinate]))throw new InvalidArgumentException('Koordinate doppelt.');$coords[$coordinate]=true;$rankNumber=filter_var($rank,FILTER_VALIDATE_INT);$otherNumber=$other===''?null:filter_var($other,FILTER_VALIDATE_INT);if($rankNumber===false||$rankNumber<0||$rankNumber>$depth||($otherNumber!==null&&($otherNumber===false||$otherNumber<0||$otherNumber>$depth))||($competitor==='')!==($otherNumber===null))throw new InvalidArgumentException('Position0=bis Messtiefe nicht gefunden; sonst1–Messtiefe. Wettbewerbername und Position gemeinsam.');if($competitor!=='')seoText($competitor,190);$points[$key]=['point_key'=>$key,'latitude_e6'=>$lat,'longitude_e6'=>$lon,'rank_position'=>$rankNumber,'competitor'=>$competitor,'competitor_rank'=>$otherNumber];if(count($points)>121)throw new InvalidArgumentException('Maximal121Messpunkte.');}if(!$points)throw new InvalidArgumentException('Keine Messpunkte.');ksort($points,SORT_STRING);return array_values($points);}finally{fclose($f);}
}
function seoStats(array $points):array {$n=count($points);$top=0;$found=0;foreach($points as $p){$r=(int)$p['rank_position'];if($r>0)$found++;if($r>=1&&$r<=3)$top++;}return ['points'=>$n,'top3'=>$top,'found'=>$found,'top3_basis_points'=>$n?intdiv($top*10000+intdiv($n,2),$n):0];}
function seoComparable(array $a,array $b):bool {$canonical=static function(array $rows):array{$r=[];foreach($rows as $p)$r[]=(int)$p['latitude_e6'].':'.(int)$p['longitude_e6'];sort($r,SORT_STRING);return $r;};return $canonical($a)===$canonical($b);}
function seoKeyword(PDO $pdo,string $keyword,string $location):int {$keyword=seoText($keyword,190);$location=seoText($location,190);$q=$pdo->prepare('SELECT id FROM seo_keywords WHERE keyword=? AND location=?');$q->execute([$keyword,$location]);if($id=$q->fetchColumn())return (int)$id;$pdo->prepare('INSERT INTO seo_keywords(keyword,location) VALUES(?,?)')->execute([$keyword,$location]);return (int)$pdo->lastInsertId();}
function seoPreview(PDO $pdo,int $admin,int $keyword,string $raw,string $time,string $source,int $depth):string {
 if($admin<1)throw new RuntimeException('Inhaberzugang erforderlich.');$q=$pdo->prepare('SELECT id FROM seo_keywords WHERE id=? AND active=1');$q->execute([$keyword]);if(!$q->fetchColumn())throw new RuntimeException('Aktives Keyword erforderlich.');$source=seoText($source,190);$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$time,new DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d\TH:i')!==$time||$d->getTimestamp()>time()+300)throw new InvalidArgumentException('Tatsächlicher Messzeitpunkt in UTC, nicht in der Zukunft.');$points=seoParse($raw,$depth);$payload=['keyword_id'=>$keyword,'measured_at'=>$d->format('Y-m-d H:i:s'),'source'=>$source,'search_depth'=>$depth,'points'=>$points,'file_hash'=>hash('sha256',$raw)];$payload['run_hash']=hash('sha256',json_encode([$keyword,$payload['measured_at'],$source,$depth,$points],JSON_THROW_ON_ERROR));$q=$pdo->prepare('SELECT run_hash FROM seo_runs WHERE keyword_id=? AND measured_at=? AND source=?');$q->execute([$keyword,$payload['measured_at'],$source]);$existing=$q->fetchColumn();$payload['duplicate']=$existing===$payload['run_hash'];$payload['conflict']=$existing!==false&&$existing!==$payload['run_hash'];$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO seo_imports(token,admin_id,keyword_id,payload) VALUES(?,?,?,?)')->execute([$token,$admin,$keyword,json_encode($payload,JSON_THROW_ON_ERROR)]);return $token;
}
function seoApply(PDO $pdo,int $admin,string $token):int {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM seo_imports WHERE token=? AND admin_id=? FOR UPDATE');$q->execute([$token,$admin]);$i=$q->fetch(PDO::FETCH_ASSOC);if(!$i)throw new RuntimeException('SEO-Vorschau fehlt.');if(strtotime($i['created_at'].' UTC')<time()-7200&&!$i['applied_at'])throw new RuntimeException('SEO-Vorschau abgelaufen.');$p=json_decode($i['payload'],true,64,JSON_THROW_ON_ERROR);$q=$pdo->prepare('SELECT active FROM seo_keywords WHERE id=? FOR UPDATE');$q->execute([$i['keyword_id']]);$active=$q->fetchColumn();$q=$pdo->prepare('SELECT id,run_hash FROM seo_runs WHERE keyword_id=? AND measured_at=? AND source=? FOR UPDATE');$q->execute([$i['keyword_id'],$p['measured_at'],$p['source']]);$old=$q->fetch(PDO::FETCH_ASSOC);if($old&&$old['run_hash']!==$p['run_hash'])throw new RuntimeException('Messkonflikt: vorhandene Historie nicht überschrieben.');if($old)$id=(int)$old['id'];else{if(!$active)throw new RuntimeException('Keyword inzwischen pausiert oder entfernt. Neue Vorschau erforderlich.');$pdo->prepare('INSERT INTO seo_runs(keyword_id,measured_at,source,search_depth,run_hash,file_hash,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$i['keyword_id'],$p['measured_at'],$p['source'],$p['search_depth'],$p['run_hash'],$p['file_hash'],$admin]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO seo_points(run_id,point_key,latitude_e6,longitude_e6,rank_position,competitor,competitor_rank) VALUES(?,?,?,?,?,?,?)');foreach($p['points'] as $row)$q->execute([$id,...array_values($row)]);gszAudit($pdo,$admin,'seo_measurement_imported',['run_id'=>$id,'keyword_id'=>(int)$i['keyword_id'],'file_hash'=>$p['file_hash'],'externally_verified'=>false]);}$pdo->prepare('UPDATE seo_imports SET applied_at=COALESCE(applied_at,UTC_TIMESTAMP()) WHERE token=?')->execute([$token]);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function seoPoints(PDO $pdo,int $run):array {$q=$pdo->prepare('SELECT * FROM seo_points WHERE run_id=? ORDER BY latitude_e6 DESC,longitude_e6,point_key');$q->execute([$run]);return $q->fetchAll(PDO::FETCH_ASSOC);}
